#!/usr/bin/python3
"""Verify bridge rejects targets generated by original camera/LiDAR bag replay.

Owns only replay and diagnostic processes in domain 95. Never opens serial.
"""
import argparse
import json
import os
from pathlib import Path
import signal
import subprocess
import time

ROOT=Path(__file__).resolve().parents[1]
BEV=ROOT.parent/'camera_lidar_bev'

def main():
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--output',type=Path,required=True)
    args=parser.parse_args()
    if os.environ.get('ROS_DOMAIN_ID')!='95':parser.error('use isolated ROS_DOMAIN_ID=95')
    args.output=args.output.resolve();args.output.mkdir(parents=True,exist_ok=False)
    bag=BEV/'bags/camera_lidar_20261010T221427_088256Z'
    mapdir=BEV/'maps/local_gps_recording_002'
    shim=args.output/'headless_view.py'
    shim.write_text("import sys\n"+f"sys.path.insert(0,{str(BEV/'tools')!r})\n"+
                    "sys.argv.insert(1,'--no-display')\nimport combined_bev_live\ncombined_bev_live.main()\n")
    children=[]
    def start(name,command):
        with (args.output/(name+'.log')).open('x') as log:
            child=subprocess.Popen(command,cwd=BEV,stdout=log,stderr=subprocess.STDOUT,start_new_session=True)
        children.append((name,child));return child
    def wait_log(name,child,text,timeout):
        end=time.monotonic()+timeout
        while time.monotonic()<end:
            if child.poll() is not None:raise RuntimeError(name+' exited; inspect its log')
            if text in (args.output/(name+'.log')).read_text():return
            time.sleep(.1)
        raise RuntimeError(name+' readiness timeout')
    try:
        bridge=start('bridge',['/usr/bin/python3',str(ROOT/'bev_dbw_bridge.py'),'--dry-run',
                              '--log-dir',str(args.output/'bridge_events'),
                              '--engage-topic','/bridge_replay_test/engage',
                              '--status-topic','/bridge_replay_test/status'])
        wait_log('bridge',bridge,'Mode=DRY RUN',10)
        context=start('context',['/usr/bin/python3',str(BEV/'tools/replay_static_context.py'),
                                 '--bag',str(bag),'--start-offset','173'])
        wait_log('context',context,'Restored exact recorded static context',20)
        viewer=start('viewer',['ros2','launch','bev_bringup','combined_bev_display.launch.py',
            'detectors:=false','road_lanes:=false','path_tracking:=true','use_sim_time:=true',
            'saved_map:='+str(mapdir),'gps_alignment:='+str(mapdir/'gps_alignment'),
            'replay_bag:='+str(bag),'reference_trajectory:='+str(mapdir/'gps_alignment/trajectory_enu.csv'),
            'viewer_script:='+str(shim)])
        wait_log('viewer',viewer,'Saved source map loaded',35)
        player=start('player',['ros2','bag','play',str(bag),'--clock','30','--rate','0.5',
            '--start-offset','173','--playback-duration','5','--disable-keyboard-controls',
            '--read-ahead-queue-size','50','--topics','/camera/front/image_raw',
            '/camera/front/camera_info','/points','/tf_static','/metadata'])
        end=time.monotonic()+25
        while time.monotonic()<end and player.poll() is None:
            if viewer.poll() is not None or bridge.poll() is not None:raise RuntimeError('diagnostic process exited')
            time.sleep(.1)
        if player.poll()!=0:raise RuntimeError('player failed or timed out')
        time.sleep(.3)
        events=[json.loads(line) for line in (args.output/'bridge_events/events.jsonl').read_text().splitlines()]
        rejected=[e for e in events if e.get('event')=='target' and e.get('reason')=='not_live_enu_rear_axle']
        commands=[e for e in events if e.get('event')=='command']
        if not rejected or commands:raise AssertionError('expected replay-labelled targets rejected with no commands')
        report=dict(source_bag=str(bag),replayed_recorded_seconds=5,playback_rate=.5,
                    replay_targets_rejected=len(rejected),command_count=len(commands),
                    hardware_ports_opened=False,physical_sensors_started=False,vehicle_commands_sent=False,
                    real_recorded_sensor_replay=True,physical_control_validated=False)
        (args.output/'report.json').write_text(json.dumps(report,indent=2)+'\n')
        print(json.dumps(report,indent=2))
    finally:
        for _,child in reversed(children):
            if child.poll() is None:
                try:os.killpg(child.pid,signal.SIGINT)
                except ProcessLookupError:pass
        end=time.monotonic()+12
        for _,child in reversed(children):
            try:child.wait(timeout=max(.1,end-time.monotonic()))
            except subprocess.TimeoutExpired:
                os.killpg(child.pid,signal.SIGKILL);child.wait()

if __name__=='__main__':main()
